import Foundation

// Handwritten narrative scenes, ported 1:1 from the web prototype's content.
let FDScenesCore: [FDSceneDef] = [
    FDSceneDef(
        id: "famille_soutien", category: "Famille", minAge: 16, maxAge: 19,
        location: "Maison familiale", character: "Ta mère",
        text: "Ta mère t'attend dans la cuisine, la lumière du couloir allumée, comme les autres soirs. Elle a préparé une assiette que tu ne mangeras pas. « Tu rentres à des heures pas possibles, tu ne vois plus personne, et tout ça pour un truc où un sur mille y arrive. » Elle ne dit pas ça méchamment. C'est pire : elle a peur pour toi.",
        choices: [
            FDChoice(label: "« C'est mon rêve, je vais y arriver »", hint: "Tu lui as dit que c'était ta vie et que tu irais au bout. Elle n'a rien répondu, mais elle a laissé la lumière du couloir allumée les soirs suivants.",
                      effects: [FDEffect(attr: .determination, delta: 2), FDEffect(rel: "famille", delta: 5), FDEffect(cond: "moral", delta: 3)]),
            FDChoice(label: "Rassurer sans trop en dire", hint: "Tu as calmé le jeu sans rien promettre. Elle a arrêté de poser des questions — et tu as arrêté de raconter.",
                      effects: [FDEffect(rel: "famille", delta: 2)]),
            FDChoice(label: "S'énerver et sortir", hint: "Tu as claqué la porte. Tu as dormi trois heures, tu t'es entraîné en colère, et le message que tu lui as envoyé à midi est resté sans réponse.",
                      effects: [FDEffect(rel: "famille", delta: -6), FDEffect(cond: "moral", delta: -4)]),
        ]),
    FDSceneDef(
        id: "vestiaire_ambiance", category: "Vestiaire", minAge: 15, maxAge: 34,
        location: "Vestiaire", character: "Capitaine de l'équipe",
        text: "Un ancien du groupe repasse ta première touche de balle du match devant tout le vestiaire, geste à l'appui, en insistant sur le contrôle raté. Les rires partent. Ce n'est pas méchant, c'est un test — celui que tout le monde passe une fois. Douze paires d'yeux attendent de voir ce que tu vas en faire.",
        choices: [
            FDChoice(label: "Rire avec lui, jouer le jeu", hint: "Tu as ri plus fort que lui et remis une couche toi-même. Le vestiaire t'a adopté sur ce rire-là.",
                      effects: [FDEffect(rel: "vestiaire", delta: 5), FDEffect(cond: "moral", delta: 2)]),
            FDChoice(label: "Répondre avec assurance", hint: "Tu lui as répondu du tac au tac, sans baisser les yeux. Il a apprécié — et il ne recommencera pas.",
                      effects: [FDEffect(attr: .leadership, delta: 2), FDEffect(rel: "vestiaire", delta: -2), FDEffect(rel: "capitaine", delta: 2)]),
            FDChoice(label: "Ignorer et se concentrer", hint: "Tu as fini de lacer tes crampons sans lever la tête. Personne ne t'a plus charrié, et personne ne t'a plus vraiment parlé non plus.",
                      effects: [FDEffect(attr: .sangfroid, delta: 1)]),
        ]),
    FDSceneDef(
        id: "entrainement_extra", category: "Entraînement", minAge: 15, maxAge: 40,
        location: "Terrain annexe", character: "Préparateur physique",
        text: "Le groupe est rentré, les cages sont rangées, et le préparateur physique t'attend au bord du terrain annexe avec des plots et un sac de ballons. « Une heure de plus, sur ton temps, pas sur le mien. » Il fait ça avec deux ou trois joueurs par saison, et jamais au hasard.",
        choices: [
            FDChoice(label: "Accepter et travailler la finition", hint: "Une heure de frappes jusqu'à ce que le geste vienne tout seul. Tu es rentré vidé, et tu as dormi comme une pierre.",
                      effects: [FDEffect(attr: .tir, delta: 2), FDEffect(cond: "fatigue", delta: 10)]),
            FDChoice(label: "Accepter et travailler le physique", hint: "Une heure de course et de renforcement, sans un ballon. Les cuisses ont crié pendant deux jours, puis elles ont tenu.",
                      effects: [FDEffect(attr: .force, delta: 1), FDEffect(attr: .endurance, delta: 1), FDEffect(cond: "fatigue", delta: 10)]),
            FDChoice(label: "Décliner, se reposer", hint: "Tu es rentré avec le groupe. Le préparateur n'a rien dit — il a juste rangé les plots sans te reproposer la séance.",
                      effects: [FDEffect(cond: "fatigue", delta: -8), FDEffect(cond: "forme", delta: 3)]),
        ]),
    FDSceneDef(
        id: "reseaux_sociaux", category: "Presse", minAge: 16, maxAge: 40,
        location: "Téléphone", character: "—",
        text: "Une vidéo de dix secondes tourne depuis hier soir : ton geste du match, ralenti, avec une musique par-dessus. Cinq cent mille vues en une nuit. La moitié des commentaires te compare à des joueurs que tu regardais à la télé, l'autre moitié explique que tu es le joueur le plus surcoté du championnat.",
        choices: [
            FDChoice(label: "Publier un message humble", hint: "Tu as posté trois lignes sobres en remerciant le groupe. Ça a plu, et personne n'a rien trouvé à redire.",
