            FDChoice(label: "Ignorer complètement", hint: "Tu n'as rien publié, tu n'as même pas relu les commentaires. La vague est passée toute seule.",
                      effects: [FDEffect(cond: "confiance", delta: 1)]),
            FDChoice(label: "Répondre à un hater", hint: "Tu as répondu à un compte anonyme. Ta réponse a fait plus de vues que la vidéo, et pas pour les bonnes raisons.",
                      effects: [FDEffect(rel: "media", delta: -5), FDEffect(cond: "moral", delta: -2)]),
        ]),
    FDSceneDef(
        id: "blessure_legere", category: "Blessure", minAge: 15, maxAge: 40,
        location: "Infirmerie du club", character: "Médecin du club",
        text: "La cuisse tire depuis la fin de la séance. Le médecin te palpe, te fait plier le genou, marque quelque chose sur sa feuille et lève les yeux : « Rien de méchant. Mais si tu joues dessus, tu sais ce qui arrive. » Le match du week-end est le seul où tu étais annoncé titulaire.",
        choices: [
            FDChoice(label: "Repos complet une semaine", hint: "Une semaine dans la salle de soins pendant que les autres jouaient. Tu es revenu entier — et le remplaçant avait marqué.",
                      effects: [FDEffect(cond: "fatigue", delta: -15), FDEffect(cond: "forme", delta: -3)]),
            FDChoice(label: "Jouer avec un strapping", hint: "Tu as joué avec le strapping. Ça a tenu quatre-vingt-dix minutes, et ça s'est réveillé le lendemain matin.",
                      effects: [FDEffect(cond: "fatigue", delta: 5), FDEffect(attr: .determination, delta: 1)],
                      riskChance: 0.18,
                      riskEffects: [FDEffect(cond: "forme", delta: -15), FDEffect(cond: "moral", delta: -8)],
                      riskText: "La blessure s'aggrave. Tu es indisponible plusieurs semaines."),
        ]),
    FDSceneDef(
        id: "agent_contact", category: "Agent", minAge: 16, maxAge: 40,
        location: "Café en ville", character: "Agent de joueurs",
        text: "Il t'attend au café en face du centre, deux téléphones posés sur la table. Il connaît ton nombre de minutes jouées, la date de fin de ton contrat, et le nom du recruteur venu te voir le mois dernier. « Tu peux signer maintenant, ou tu peux attendre que quelqu'un d'autre décide de ta carrière à ta place. »",
        choices: [
            FDChoice(label: "Signer avec lui", hint: "Tu as signé au café, sur une table encore mouillée. Il a passé son premier appel dans la foulée, devant toi.",
                      effects: [FDEffect(rel: "agent", delta: 15), FDEffect(cond: "confiance", delta: 3)]),
            FDChoice(label: "Rester prudent, sans engagement", hint: "Tu as gardé sa carte sans rien signer. Il rappellera — mais entre-temps, personne ne défend ton dossier.", effects: []),
        ]),
    FDSceneDef(
        id: "presse_conference", category: "Presse", minAge: 18, maxAge: 40,
        location: "Salle de presse", character: "Journaliste",
        text: "La salle de presse est pleine, les micros du club posés devant toi. La question tombe au bout de deux minutes, celle que tout le monde attendait : « On dit que de grands clubs se sont renseignés sur vous. Vous confirmez ? » Ton président est assis au fond de la salle.",
        choices: [
            FDChoice(label: "Rester humble, parler collectif", hint: "Tu as tout ramené au groupe et au prochain match. Le président a hoché la tête au fond de la salle.",
                      effects: [FDEffect(rel: "media", delta: 4), FDEffect(rel: "vestiaire", delta: 2)]),
            FDChoice(label: "Affirmer ses ambitions", hint: "Tu as dit tout haut que tu visais plus grand. Les titres du lendemain t'ont donné raison ; le vestiaire, moins.",
                      effects: [FDEffect(cond: "reputation", delta: 5), FDEffect(rel: "president", delta: -4)]),
        ]),
    FDSceneDef(
        id: "sponsor_offre", category: "Sponsor", minAge: 17, maxAge: 40,
        location: "Bureaux d'une marque", character: "Représentant marque sportive",
        text: "Une marque d'équipement te reçoit dans ses bureaux : chaussures fournies, une somme mensuelle correcte, en échange de publications régulières et de deux journées de tournage par an. Le contrat est court, les obligations aussi — mais elles tombent en pleine saison.",
        choices: [
            FDChoice(label: "Accepter", hint: "Tu as signé. L'argent tombe chaque mois, et les deux journées de tournage sont tombées la semaine du derby.",
                      effects: [FDEffect(money: 4000), FDEffect(cond: "reputation", delta: 2), FDEffect(cond: "forme", delta: -1)]),
            FDChoice(label: "Refuser pour rester concentré", hint: "Tu as refusé pour garder tes semaines libres. Le staff a apprécié, ton compte en banque moins.",
