    FDSceneDef(
        id: "couple_rencontre", category: "Couple", minAge: 18, maxAge: 40, once: true,
        location: "Soirée d'équipe", character: "—",
        text: "La soirée du club se termine, la salle se vide, et une conversation commencée par hasard dure depuis deux heures. On ne t'a pas parlé de football une seule fois de la soirée — ça faisait longtemps. Ton chauffeur attend dehors depuis vingt minutes.",
        choices: [
