        text: "Le club te laisse le studio de fonction encore un mois, puis il faudra partir. L'agent immobilier te fait visiter deux appartements le même jour : un simple, à dix minutes du centre d'entraînement, et un plus beau en plein centre-ville, à quarante minutes de route et le double de loyer.",
        choices: [
            FDChoice(label: "Appartement simple près du centre d'entraînement", hint: "Dix minutes de trajet, un intérieur sans charme, et une heure de sommeil de plus chaque matin. Personne ne viendra jamais admirer l'appartement.",
