    FDSceneDef(
        id: "selection_convocation_jeune", category: "Sélection", minAge: 16, maxAge: 19, once: true,
        location: "Courrier officiel", character: "Fédération nationale",
        text: "Le courrier officiel est posé sur ta place au vestiaire, l'écusson de la fédération en haut à gauche. Le staff a fait semblant de ne rien voir pour te laisser l'ouvrir. Rassemblement dans trois semaines, avec la sélection nationale, pour la première fois de ta vie.",
        choices: [
            FDChoice(label: "Répondre présent avec fierté", hint: "Tu as répondu présent le soir même. Ton père a demandé à voir la lettre trois fois.",
