    FDSceneDef(
        id: "transfert_interet", category: "Transfert", minAge: 19, maxAge: 33,
        location: "Rumeur de marché", character: "Agent",
        text: "Ton agent t'appelle un lundi matin, entre deux séances. Un club d'un championnat au-dessus s'est renseigné sur ta clause et ta fin de contrat — pas une offre, juste ce coup de fil qui change la façon dont on regarde son propre vestiaire. « Ils veulent savoir si tu es ouvert. »",
        choices: [
            FDChoice(label: "Se dire prêt à partir", hint: "Tu as fait dire que tu écouterais. L'information est remontée au club avant même la fin de la semaine.",
                      effects: [FDEffect(rel: "president", delta: -5), FDEffect(cond: "confiance", delta: 5)]),
            FDChoice(label: "Rester loyal pour l'instant", hint: "Tu as fait dire que tu étais bien ici. Le club te l'a rendu ; ton agent a raccroché sans commenter.",
