        location: "Cérémonie du club", character: "Président du club",
        text: "Le club a loué une salle pour fêter la saison. Le président égrène les noms au micro, et le tien arrive dans la liste des artisans. Tes coéquipiers frappent sur les tables. Il y a deux ans, personne ici ne savait comment tu t'appelais.",
        choices: [
            FDChoice(label: "Savourer avec le groupe", hint: "Tu as fêté ça avec le groupe jusqu'à la fin de la soirée, sans discours et sans photos.",
                      effects: [FDEffect(rel: "vestiaire", delta: 5), FDEffect(cond: "reputation", delta: 4)]),
        ],
        condition: { p in p.cond.forme >= 70 }),
    FDSceneDef(
