        text: "Le vestiaire s'est vidé, tu es encore assis, une poche de glace sur chaque genou. Ce n'est pas la séance qui a été dure, c'est le lendemain de la séance. Tu as commencé à calculer combien de saisons il te reste — et ça, tu ne l'avais jamais fait avant. La retraite est accessible à tout moment depuis l'onglet Options.",
