            FDChoice(label: "Commencer à préparer la reconversion", hint: "Tu as passé tes premiers coups de fil pour l'après. Ça t'a rassuré, et ça t'a coûté un peu de rage.",
                      effects: [FDEffect(cond: "moral", delta: 5)]),
        ]),
    FDSceneDef(
