        text: "Match clé dans vingt minutes, et le vestiaire est trop silencieux. Le capitaine a parlé, ça n'a rien changé. Deux ou trois regards se tournent vers toi, ceux qui savent que tu tiens le groupe quand ça va mal. Personne ne te demande rien à voix haute.",
