        text: "Deux dossiers, deux carrières différentes. Un club moins huppé double ton salaire, tout de suite, sans discuter. Un autre, mieux installé, propose moins d'argent mais une place dans un vrai projet. Ton agent pousse pour le premier — sa commission aussi.",
        choices: [
