        text: "Les caméras t'attendent à la sortie du vestiaire, encore chaud du match que tu viens de faire. Le diffuseur cherche une image forte pour son ouverture, le community manager du club filme aussi. Ce qui sort d'ici dans les trente secondes va tourner en boucle jusqu'à demain soir.",
        choices: [
