        text: "Finale, 90e minute, 1-1, et l'arbitre désigne le point. Le stade s'est mis à hurler puis s'est tu d'un coup. Le gardien adverse marche sur sa ligne en te fixant. Tu poses le ballon, tu recules de sept pas, et pendant deux secondes tu n'entends plus rien du tout.",
