    FDSceneDef(
        id: "moment_decisif_contre", category: "Moment décisif", minAge: 18, maxAge: 40,
        location: "Contre-attaque, 88e minute", character: "1-1, un coéquipier démarqué",
        text: "88e minute d'une finale à 1-1, deux contre un, quarante mètres devant toi. Le défenseur recule sans oser plonger, ton coéquipier hurle sur ta gauche, complètement seul. Le banc est debout. Tu as deux secondes pour choisir entre le geste dont on parlera et le geste juste.",
        choices: [
            FDChoice(label: "Y aller seul et frapper", hint: "Tu as gardé le ballon et frappé. La postérité tenait dans ce ballon-là, et le gardien l'a repoussé du bout des doigts.",
                      effects: [FDEffect(attr: .tir, delta: 2), FDEffect(cond: "confiance", delta: 3)],
                      riskChance: 0.35,
                      riskEffects: [FDEffect(rel: "vestiaire", delta: -4)],
                      riskText: "Le tir passe au-dessus. Le coéquipier démarqué n'a pas caché son agacement."),
            FDChoice(label: "Servir le coéquipier au bon moment", hint: "Tu as attendu le dernier moment et tu l'as servi. Il a marqué, il est venu te chercher, et le stade a compris qui avait fait le but.",
                      effects: [FDEffect(attr: .vision, delta: 2), FDEffect(rel: "vestiaire", delta: 5)]),
        ],
        condition: { p in p.cond.reputation >= 35 },
        positions: FDPosition.allCases.filter { $0 != .gardien }),

    // MARK: Position-specific training, vestiaire and press scenes

    FDSceneDef(
        id: "entrainement_gardien", category: "Entraînement", minAge: 15, maxAge: 40,
        location: "Cage d'entraînement", character: "Entraîneur des gardiens",
        text: "L'entraîneur des gardiens t'isole une heure : ballons hauts au milieu des corps, sorties dans les pieds, relances sous pression avec deux attaquants lancés sur toi. « Tu as un trou dans ton jeu. On va décider ensemble par quoi on le bouche. »",
        choices: [
            FDChoice(label: "Travailler les sorties aériennes", hint: "Une heure de sorties aériennes au milieu des coudes. Tu es sorti avec l'arcade ouverte et un vrai domaine en plus.",
                      effects: [FDEffect(attr: .placement, delta: 2), FDEffect(cond: "fatigue", delta: 8)]),
            FDChoice(label: "Travailler le jeu au pied", hint: "Une heure de relances sous pression, jusqu'à ce que le premier contrôle vienne sans réfléchir.",
                      effects: [FDEffect(attr: .control, delta: 2), FDEffect(cond: "fatigue", delta: 6)]),
        ],
        positions: [.gardien]),
    FDSceneDef(
        id: "entrainement_defenseur", category: "Entraînement", minAge: 15, maxAge: 40,
        location: "Terrain annexe", character: "Adjoint défensif",
        text: "Séance vidéo d'abord : l'adjoint arrête l'image sur tes deux erreurs de la semaine, sans commenter, en te laissant les regarder. Puis terrain, ateliers, répétitions. « Un défenseur progresse à un endroit précis. Choisis lequel. »",
        choices: [
            FDChoice(label: "Travailler le placement défensif", hint: "Deux heures de placement, jusqu'à ce que la position juste devienne un réflexe. Ennuyeux, et payant.",
                      effects: [FDEffect(attr: .placement, delta: 2), FDEffect(cond: "fatigue", delta: 7)]),
            FDChoice(label: "Travailler l'anticipation", hint: "Deux heures à lire les intentions avant qu'elles arrivent. Tu as intercepté trois ballons le week-end suivant.",
                      effects: [FDEffect(attr: .interception, delta: 2), FDEffect(cond: "fatigue", delta: 7)]),
        ],
        positions: [.defenseur]),
    FDSceneDef(
        id: "entrainement_milieu", category: "Entraînement", minAge: 15, maxAge: 40,
        location: "Terrain annexe", character: "Adjoint tactique",
        text: "Conservation à haute intensité dans un carré trop petit : quatre contre quatre, deux touches, les anciens qui ne te font aucun cadeau. L'adjoint tactique siffle à chaque ballon perdu et il siffle beaucoup. Il t'arrête au bout d'une heure : « Tu veux voir, ou tu veux sécuriser ? »",
        choices: [
            FDChoice(label: "Travailler la vision de jeu", hint: "Une heure la tête haute, à chercher le ballon qui casse une ligne. Tu en as perdu beaucoup, et trouvé deux magnifiques.",
                      effects: [FDEffect(attr: .vision, delta: 2), FDEffect(cond: "fatigue", delta: 7)]),
            FDChoice(label: "Travailler la passe sous pression", hint: "Une heure à jouer juste sous pression, sans jamais forcer. Pas un ballon perdu, pas un ballon décisif.",
                      effects: [FDEffect(attr: .passe, delta: 2), FDEffect(cond: "fatigue", delta: 7)]),
        ],
        positions: [.milieu]),
    FDSceneDef(
        id: "entrainement_attaquant", category: "Entraînement", minAge: 15, maxAge: 40,
        location: "Terrain annexe", character: "Adjoint offensif",
        text: "Séance de finition à répétition : appels dans le dos, centres en première intention, dernier geste avec le gardien lancé sur toi. Tu as raté les quatre premiers ballons et l'adjoint offensif n'a rien dit. Il attend de voir sur quoi tu vas t'acharner.",
        choices: [
            FDChoice(label: "Travailler les appels de balle", hint: "Une heure d'appels dans le dos jusqu'à prendre les défenseurs à contretemps sans y penser.",
                      effects: [FDEffect(attr: .vitesse, delta: 2), FDEffect(cond: "fatigue", delta: 7)]),
            FDChoice(label: "Travailler la finition", hint: "Une heure de dernier geste, jusqu'à ce que le gardien ne sache plus de quel côté partir.",
                      effects: [FDEffect(attr: .tir, delta: 2), FDEffect(cond: "fatigue", delta: 7)]),
        ],
        positions: [.attaquant]),
    FDSceneDef(
        id: "vestiaire_solitude_gardien", category: "Vestiaire", minAge: 17, maxAge: 40,
        location: "Vestiaire, après une défaite", character: "Coéquipiers de champ",
        text: "Une frappe de trente mètres qui te passe entre les mains, et le match est perdu. Le vestiaire est silencieux, tout le monde se change en regardant le sol. Personne ne t'accable, personne ne vient non plus. C'est la solitude particulière du poste : dix joueurs ratent, un seul se voit.",
        choices: [
            FDChoice(label: "Prendre la parole et assumer", hint: "Tu t'es levé et tu as assumé devant tout le monde, sans chercher d'excuse. Le capitaine est venu te serrer la main après.",
                      effects: [FDEffect(attr: .leadership, delta: 3), FDEffect(rel: "coach", delta: 3)]),
            FDChoice(label: "Encaisser en silence, revoir les images seul", hint: "Tu n'as rien dit, tu es rentré, et tu as revu les images seul jusqu'à deux heures du matin.",
                      effects: [FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "confiance", delta: -2)]),
        ],
        positions: [.gardien]),
    FDSceneDef(
        id: "presse_secheresse_but", category: "Presse", minAge: 18, maxAge: 40,
        location: "Zone mixte", character: "Journaliste",
        text: "Trois matchs sans marquer, et la question tombe en zone mixte, micro tendu, caméra allumée : « La pression commence à peser ? » Le journaliste sait exactement ce qu'il fait — c'est la réponse qui fera le titre, pas la question.",
        choices: [
            FDChoice(label: "Assumer la pression avec confiance", hint: "Tu as assumé la pression en face, en disant que c'était ton métier. Le titre du lendemain était bon pour toi.",
                      effects: [FDEffect(cond: "confiance", delta: 4), FDEffect(rel: "media", delta: 3)]),
            FDChoice(label: "Relativiser, parler du collectif", hint: "Tu as ramené ça au collectif et aux victoires. Personne n'a repris la réponse, ce qui était l'objectif.",
                      effects: [FDEffect(rel: "vestiaire", delta: 3)]),
        ],
        condition: { p in p.cond.reputation >= 20 },
        positions: [.attaquant]),
    FDSceneDef(
        id: "presse_defenseur_ombre", category: "Presse", minAge: 18, maxAge: 40,
        location: "Zone mixte", character: "Journaliste",
        text: "« On ne parle jamais de vous. Toujours de ceux qui marquent. Ça ne vous frustre pas, à la longue ? » Le journaliste a raison et il le sait. Ton nom n'est apparu que deux fois dans la presse cette saison, les deux fois pour une erreur.",
        choices: [
            FDChoice(label: "Revendiquer la fierté du travail de l'ombre", hint: "Tu as revendiqué le métier de l'ombre, sans amertume. La réponse a été reprise partout, et les défenseurs t'ont écrit.",
                      effects: [FDEffect(cond: "reputation", delta: 3), FDEffect(rel: "coach", delta: 3)]),
            FDChoice(label: "Botter en touche avec humour", hint: "Tu as répondu par une vanne et tout le monde a ri. On n'a pas parlé de toi pour autant.",
                      effects: [FDEffect(rel: "media", delta: 3)]),
        ],
        condition: { p in p.cond.reputation >= 20 },
        positions: [.defenseur]),
    FDSceneDef(
        id: "vestiaire_provocateur", category: "Vestiaire", minAge: 17, maxAge: 34,
        location: "Vestiaire, avant l'entraînement", character: "Coéquipier adverse la veille",
        text: "Un joueur de l'équipe qu'on affronte dimanche a chambré ton club sur les réseaux, avec les noms et le sourire. La vidéo est passée dans toutes les conversations du vestiaire depuis ce matin. Le groupe attend de voir ce que tu vas faire, toi qui n'as jamais eu la langue dans ta poche.",
        choices: [
            FDChoice(label: "Répondre publiquement, sans filtre", hint: "Tu as répondu publiquement, sans filtre. Le vestiaire a adoré, le service com du club beaucoup moins.",
                      effects: [FDEffect(cond: "reputation", delta: 6), FDEffect(rel: "fans", delta: 4)],
                      riskChance: 0.3,
                      riskEffects: [FDEffect(rel: "president", delta: -5), FDEffect(cond: "moral", delta: -3)],
                      riskText: "Le club te rappelle à l'ordre : la sortie n'est pas passée inaperçue en interne."),
            FDChoice(label: "Laisser parler le terrain", hint: "Tu n'as rien dit de la semaine et tout dit dimanche. C'est la version qui reste la plus longtemps.",
                      effects: [FDEffect(attr: .determination, delta: 3)]),
        ],
        condition: { p in p.personality == .provocateur }),
    FDSceneDef(
        id: "presse_joueur_reserve", category: "Presse", minAge: 17, maxAge: 40,
        location: "Zone mixte", character: "Journaliste",
        text: "Les questions s'enchaînent en zone mixte, six micros sous le menton, et tu détestes ça depuis toujours. Sur le terrain tu sais quoi faire de chaque seconde ; ici, chaque silence dure trop longtemps et se retrouve monté au journal du soir.",
        choices: [
            FDChoice(label: "Répondre brièvement, sans en dire trop", hint: "Tu as répondu en trois phrases et tu es parti. Correct, oubliable, et personne ne t'a cherché.",
                      effects: [FDEffect(attr: .sangfroid, delta: 2)]),
            FDChoice(label: "Forcer le contact avec les médias", hint: "Tu t'es forcé, tu es resté, tu as pris les questions une par une. C'était laborieux, et les journalistes s'en souviennent.",
                      effects: [FDEffect(rel: "media", delta: 4), FDEffect(cond: "confiance", delta: -2)]),
        ],
        condition: { p in p.personality == .reserve }),

    // MARK: - Rivalité (persistent rival, introduced at 17, followed loosely all career)
    FDSceneDef(
        id: "rivalite_intro", category: "Rivalité", minAge: 17, maxAge: 17, once: true,
        location: "Centre de formation", character: "{rival}",
        text: "Il a ton âge, il joue à cent kilomètres d'ici, et depuis six mois les journaux ne parlent que de lui : {rival}. Même les gens de ton club citent son nom pour dire ce qu'un joueur de ta génération devrait être. Vous ne vous êtes jamais croisés sur un terrain. Ça viendra.",
        choices: [
            FDChoice(label: "Se jurer de le dépasser", hint: "Tu t'es juré de le dépasser, et tu as accroché son nom quelque part dans ta tête pour dix ans.", tag: "CARBURANT",
                      effects: [FDEffect(attr: .determination, delta: 3), FDEffect(cond: "confiance", delta: 3)]),
            FDChoice(label: "Se concentrer sur sa propre progression", hint: "Tu as décidé que sa carrière ne te regardait pas. Tu as tenu — presque toujours.",
                      effects: [FDEffect(attr: .sangfroid, delta: 2)]),
        ]),
    FDSceneDef(
        id: "rivalite_clash_media", category: "Rivalité", minAge: 19, maxAge: 32,
        location: "Zone mixte", character: "Journaliste",
        text: "Zone mixte, fin de match, et le journaliste sort son téléphone pour te lire la citation mot pour mot : {rival} vient d'expliquer en direct qu'il est « largement au-dessus » de toi. La salle s'est tue. Le micro reste tendu, et il ne bougera pas tant que tu n'auras pas parlé.",
        choices: [
            FDChoice(label: "Répondre par une pique bien sentie", hint: "Tu as répondu par une pique qui a fait le tour du pays en deux heures. Il a lu, tout le monde a lu.", tag: "CLASH",
                      effects: [FDEffect(cond: "reputation", delta: 6), FDEffect(rel: "fans", delta: 3)],
                      riskChance: 0.25,
                      riskEffects: [FDEffect(rel: "president", delta: -4), FDEffect(cond: "moral", delta: -3)],
                      riskText: "Le club te recadre en interne : la sortie médiatique n'est pas passée inaperçue."),
            FDChoice(label: "Rester au-dessus de la mêlée", hint: "Tu as dit que tu répondrais sur le terrain et tu es parti. Le silence a fait plus de bruit que sa phrase.",
                      effects: [FDEffect(attr: .sangfroid, delta: 2)]),
        ]),
    FDSceneDef(
        id: "rivalite_terrain_duel", category: "Rivalité", minAge: 19, maxAge: 32,
        location: "Terrain", character: "{rival}",
        text: "Vous êtes enfin sur le même terrain, à dix mètres l'un de l'autre pendant l'hymne, sans vous regarder. Les caméras ne suivent que ça depuis l'échauffement. {rival} joue dans ton couloir. Le match dure quatre-vingt-dix minutes, votre duel dure depuis six ans.",
        choices: [
            FDChoice(label: "Le chercher sur chaque ballon", hint: "Tu l'as cherché sur chaque ballon, jusqu'à la faute, jusqu'au carton. Il a fini le match agacé, et toi épuisé.", tag: "PROVOCATION",
                      effects: [FDEffect(attr: .determination, delta: 3)],
                      riskChance: 0.22,
                      riskEffects: [FDEffect(rel: "coach", delta: -4), FDEffect(cond: "moral", delta: -3)],
                      riskText: "Le duel dégénère. Le coach n'apprécie pas ton attitude sur ce match."),
            FDChoice(label: "Garder son sang-froid, jouer son jeu", hint: "Tu as ignoré le duel et joué ton match. C'est toi qui es sorti sous les applaudissements.",
                      effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(attr: .placement, delta: 2)]),
        ]),
    FDSceneDef(
        id: "rivalite_depassement", category: "Rivalité", minAge: 24, maxAge: 34,
        location: "Vestiaire", character: "Coéquipier",
        text: "Un coéquipier fait défiler les statistiques sur son téléphone dans le vestiaire, puis te tend l'écran sans rien dire. Buts, passes, minutes, note moyenne : tu es passé devant {rival} cette saison, pour la première fois depuis que vous êtes comparés. « Tu le sens, ou pas ? »",
        choices: [
            FDChoice(label: "Savourer, sans le crier sur les toits", hint: "Tu as souri sans rien dire et tu as gardé ça pour toi. Il y a des choses qu'on ne crie pas.",
                      effects: [FDEffect(cond: "confiance", delta: 4), FDEffect(cond: "moral", delta: 3)]),
            FDChoice(label: "Rester humble, la rivalité continue", hint: "Tu as répondu que ça ne voulait rien dire tant qu'il jouait encore. C'est vrai, et ça t'a tenu éveillé.",
                      effects: [FDEffect(rel: "vestiaire", delta: 3)]),
        ]),

    // MARK: - Identité de jeu (once, ~21 ans — permanent play-style lock)
    FDSceneDef(
        id: "identite_jeu", category: "Identité de jeu", minAge: 21, maxAge: 22, once: true,
        location: "Bureau du staff technique", character: "Analyste vidéo",
        text: "L'analyste vidéo a préparé quarante minutes de tes ballons de la saison, classés par famille. Il coupe le projecteur et se retourne : « À ton âge, un joueur arrête de tout essayer et devient quelqu'un. Ce que tu choisis là, on va le travailler pendant les dix prochaines années. »",
        choices: [
            FDChoice(label: "Le Régisseur — orchestrer le jeu avant de conclure", hint: "Tu deviens celui qui fait jouer les autres avant de conclure. Le staff a réorganisé les séances autour de ça.",
                      effects: [FDEffect(attr: .vision, delta: 4), FDEffect(attr: .passe, delta: 4), FDEffect(attr: .tir, delta: -3)],
                      setPlayStyle: "Le Régisseur"),
            FDChoice(label: "Le Renard — vivre dans la surface, se nourrir des occasions", hint: "Tu deviens celui qui vit dans la surface et attend son ballon. Un but tous les deux matchs, et rien entre les deux.",
                      effects: [FDEffect(attr: .tir, delta: 5), FDEffect(attr: .placement, delta: 3), FDEffect(attr: .passe, delta: -3)],
                      setPlayStyle: "Le Renard"),
            FDChoice(label: "Le Métronome — sécuriser chaque ballon, ne jamais le perdre", hint: "Tu deviens celui qui ne perd jamais le ballon. Personne ne le remarquera, tout le monde le sentira.",
                      effects: [FDEffect(attr: .control, delta: 4), FDEffect(attr: .sangfroid, delta: 3), FDEffect(attr: .dribble, delta: -3)],
                      setPlayStyle: "Le Métronome"),
            FDChoice(label: "L'Électron libre — improviser, prendre des risques", hint: "Tu deviens celui qu'on ne peut pas prévoir. Ça produit des gestes magnifiques et des soirées catastrophiques.",
                      effects: [FDEffect(attr: .dribble, delta: 5), FDEffect(attr: .vitesse, delta: 2), FDEffect(attr: .placement, delta: -3)],
                      setPlayStyle: "L'Électron libre"),
        ]),

    // MARK: - Hygiène de vie
    FDSceneDef(
        id: "hygiene_soiree_groupe", category: "Hygiène de vie", minAge: 18, maxAge: 34,
        location: "Ville, en soirée", character: "Coéquipiers",
        text: "Victoire, et le groupe organise une sortie en ville dans la foulée. Le message tourne dans la boucle du vestiaire, les anciens y vont, les jeunes suivent. Reprise demain matin à neuf heures, avec test physique. Ceux qui ne viennent pas, on le remarque aussi.",
        choices: [
            FDChoice(label: "Se joindre au groupe, dans la limite du raisonnable", hint: "Tu y es allé, tu es rentré tôt, tu as bu de l'eau toute la soirée. Le compromis a marché à moitié.",
                      effects: [FDEffect(rel: "vestiaire", delta: 5), FDEffect(cond: "moral", delta: 3), FDEffect(cond: "forme", delta: -3)]),
            FDChoice(label: "Rentrer se reposer", hint: "Tu es rentré directement. Test physique impeccable le lendemain, et une conversation de vestiaire que tu n'as pas comprise.",
                      effects: [FDEffect(cond: "forme", delta: 3), FDEffect(rel: "vestiaire", delta: -2)]),
        ]),
    FDSceneDef(
        id: "hygiene_ecrans_tard", category: "Hygiène de vie", minAge: 16, maxAge: 30,
        location: "Chambre d'hôtel", character: "—",
        text: "Chambre d'hôtel, veille de match, il est une heure et quart. Tu enchaînes les parties en ligne avec le son dans un écouteur pour ne pas réveiller ton coéquipier de chambre. Réveil à sept heures. Tu te dis « encore une » depuis à peu près deux heures.",
        choices: [
            FDChoice(label: "Couper les écrans, dormir", hint: "Tu as coupé et posé le téléphone à l'autre bout de la chambre. Tu t'es levé frais, ce qui s'est vu dès l'échauffement.",
                      effects: [FDEffect(cond: "forme", delta: 3)]),
            FDChoice(label: "Continuer encore un peu", hint: "Tu as continué jusqu'à trois heures. Tu as joué le match, et le match a duré très longtemps.",
                      effects: [FDEffect(cond: "forme", delta: -3), FDEffect(cond: "fatigue", delta: 8)]),
        ]),
    FDSceneDef(
        id: "hygiene_a_lecart", category: "Hygiène de vie", minAge: 18, maxAge: 34,
        location: "Centre d'entraînement", character: "Noyau dur du vestiaire",
        text: "Le noyau dur du vestiaire a ses habitudes : mêmes repas, mêmes sorties, même table. Toi tu as ta routine, tes horaires, ton coin. Personne ne t'en veut ouvertement — mais quand le groupe se raconte quelque chose, tu apprends toujours l'histoire avec un jour de retard.",
        choices: [
            FDChoice(label: "Assumer sa différence", hint: "Tu as assumé ta manière de faire jusqu'au bout. Tu es resté à côté du groupe, et parfaitement en forme.",
                      effects: [FDEffect(attr: .sangfroid, delta: 2), FDEffect(rel: "vestiaire", delta: -2)]),
            FDChoice(label: "Forcer le rapprochement", hint: "Tu as fait l'effort d'aller vers eux, plusieurs fois, sans y trouver ton compte. Le groupe s'est ouvert, ta routine a sauté.",
                      effects: [FDEffect(rel: "vestiaire", delta: 4), FDEffect(cond: "confiance", delta: -2)]),
        ]),

    // MARK: - Préparation
    FDSceneDef(
        id: "preparation_donnees", category: "Préparation", minAge: 20, maxAge: 40,
        location: "Salle vidéo", character: "Analyste de la performance",
        text: "L'analyste te reçoit avec quatre écrans : distance parcourue, sprints, zones de perte de balle, pourcentages de passes par tiers de terrain. Tout est là, chiffré, découpé. Il attend ton avis. Tu as joué au football toute ta vie sans regarder une seule de ces courbes.",
        choices: [
            FDChoice(label: "Tout décortiquer, s'en nourrir", hint: "Tu as tout décortiqué avec lui, deux fois par semaine. Tu joues plus juste, et tu réfléchis un peu plus longtemps avant de tenter.",
                      effects: [FDEffect(attr: .vision, delta: 2), FDEffect(attr: .placement, delta: 2), FDEffect(cond: "fatigue", delta: 5)]),
            FDChoice(label: "Garder l'instinct, ignorer les chiffres", hint: "Tu as refermé l'ordinateur et gardé ton instinct. Tu as fait deux gestes cette saison qu'aucune donnée n'aurait recommandés.",
                      effects: [FDEffect(cond: "confiance", delta: 2)]),
        ]),
    FDSceneDef(
        id: "preparation_routine_recup", category: "Préparation", minAge: 29, maxAge: 40,
        location: "Centre de récupération", character: "Kinésithérapeute",
        text: "Après trente ans, la récupération est devenue le vrai métier : cryothérapie, soins ciblés, compression, une heure et demie de routines avant même de toucher un ballon. Le kiné te tend le protocole complet. Les jeunes du groupe traversent le vestiaire en riant, déjà changés.",
        choices: [
            FDChoice(label: "En faire une science exacte", hint: "Tu as suivi le protocole à la minute près toute la saison. Ton corps a tenu — tes journées font douze heures.",
                      effects: [FDEffect(attr: .force, delta: 3), FDEffect(cond: "forme", delta: 3)]),
            FDChoice(label: "Écouter son corps au feeling", hint: "Tu as géré au feeling, séance par séance. Certaines semaines ça a très bien marché, d'autres non.",
                      effects: [FDEffect(attr: .sangfroid, delta: 2)]),
        ]),

    // MARK: - Supporters (fin de carrière)
    FDSceneDef(
        id: "supporters_lettre_fan", category: "Supporters", minAge: 28, maxAge: 40,
        location: "Courrier du club", character: "Jeune supporter",
        text: "Une lettre manuscrite arrive au centre, glissée dans le courrier du club. Un gamin raconte le match où son père l'a emmené te voir, ton nom au dos de son maillot, et il te demande si un jour il pourra jouer comme toi. Il a écrit son adresse en gros, deux fois, au cas où.",
        choices: [
            FDChoice(label: "Répondre personnellement", hint: "Tu as répondu à la main et envoyé un maillot dédicacé. Sa mère a publié la lettre, et la ville entière l'a lue.",
                      effects: [FDEffect(rel: "fans", delta: 5), FDEffect(cond: "moral", delta: 3)]),
            FDChoice(label: "Transmettre au service communication", hint: "Tu as transmis au service communication, qui a envoyé le pack habituel avec une signature imprimée.",
                      effects: [FDEffect(rel: "fans", delta: 2)]),
        ]),
    FDSceneDef(
        id: "supporters_tifo", category: "Supporters", minAge: 22, maxAge: 40,
        location: "Tribune", character: "Groupe de supporters",
        text: "Le virage déploie un tifo de vingt mètres à ton effigie avant le coup d'envoi, avec ta célébration reproduite au pinceau. Ils y ont passé des semaines. Le stade entier s'est levé, l'arbitre attend, et tes coéquipiers te poussent du coude en riant.",
