                      effects: [FDEffect(rel: "fans", delta: 4), FDEffect(cond: "confiance", delta: 3)]),
            FDChoice(label: "Rester concentré sur l'échauffement", hint: "Tu as fait un signe rapide et tu as repris ton échauffement. Le virage a chanté quand même, un peu moins fort.",
                      effects: [FDEffect(attr: .sangfroid, delta: 2)]),
        ]),
]

