    FDSceneDef(
        id: "gmb_tournoi_charite", category: "Club", minAge: 21, maxAge: 38,
        location: "Un stade municipal", character: "Un organisateur",
        text: "On te propose de financer un tournoi caritatif à ton nom. 28 000 € d'organisation, et un week-end entier de ton temps.",
